package com.ruoyi.ai.mapper; import java.util.List;import org.apache.ibatis.annotations.*;import com.ruoyi.ai.domain.AiPageConfig;public interface AiPageConfigMapper{String FIELDS="select page_id as pageId,route,page_name as pageName,enabled,create_by as createBy,create_time as createTime,update_by as updateBy,update_time as updateTime ";@Select(FIELDS+"from ai_page_config order by route")List<AiPageConfig> selectAll();@Select(FIELDS+"from ai_page_config where route=#{route} limit 1")AiPageConfig selectByRoute(String route);@Update("update ai_page_config set enabled=#{enabled},update_by=#{username},update_time=sysdate() where page_id=#{pageId}")int updateEnabled(@Param("pageId")Long pageId,@Param("enabled")String enabled,@Param("username")String username);}
